// WebAuthn promises can outlive a dismissed passkey sheet, so cap them with a deadline.
import { DeadlineExceededError, type DeadlinePolicy } from "@sand/dune/scheduling";

export const PASSKEY_STALL_MS = 60_000;

export interface PasskeyStallReport {
	readonly method: string;
	readonly since: number;
}

export function raceWithPasskeyStallDeadline<T>(options: {
	readonly policy: DeadlinePolicy;
	readonly method: string;
	readonly since: number;
	readonly call: Promise<T>;
	readonly reportStall: (report: PasskeyStallReport) => void;
	readonly buildStallError: () => Error;
}): Promise<T> {
	return options.policy
		.run(() => options.call)
		.catch((error: unknown) => {
			if (error instanceof DeadlineExceededError) {
				options.reportStall({ method: options.method, since: options.since });
				throw options.buildStallError();
			}
			throw error;
		});
}
