// Node-safe scheduling entry: the semantic time policies, their types, and
// the clock surface with no React in the import graph, so Node executable
// targets (the node-agent-coordinator) can consume policies without
// pulling the renderer composition the root entry carries.
import { realClock } from "./internal/scheduling/clock.js";
import {
	createDeadlinePolicy as createDeadlinePolicyWithClock,
	createDebouncePolicy as createDebouncePolicyWithClock,
	createExpiryPolicy as createExpiryPolicyWithClock,
	createIdleWatchdogPolicy as createIdleWatchdogPolicyWithClock,
	createPollingPolicy as createPollingPolicyWithClock,
	createRetryPolicy as createRetryPolicyWithClock,
	createTaskBoundaryPolicy as createTaskBoundaryPolicyWithClock,
	type DeadlinePolicy,
	type DeadlinePolicyOptions,
	type DebouncePolicy,
	type DebouncePolicyOptions,
	type ExpiryPolicy,
	type ExpiryPolicyOptions,
	type IdleWatchdogPolicy,
	type IdleWatchdogPolicyOptions,
	type PollingPolicy,
	type PollingPolicyOptions,
	type RetryPolicy,
	type RetryPolicyOptions,
	type TaskBoundaryPolicy,
	type TaskBoundaryPolicyOptions,
} from "./internal/scheduling/policies.js";

// The clock value is exported here and nowhere else public: process
// composition roots inject it into modules that read monotonicNow(), while
// renderer code keeps the root entry's policies-only surface.
export { realClock };
export type { Clock, Disposable } from "./internal/scheduling/clock.js";

export { DeadlineExceededError } from "./internal/scheduling/policies.js";
export type {
	DeadlinePolicy,
	DeadlinePolicyOptions,
	DebouncedFunction,
	DebouncePolicy,
	DebouncePolicyOptions,
	Delay,
	ExpiryPolicy,
	ExpiryPolicyOptions,
	IdleWatchdogHandle,
	IdleWatchdogPolicy,
	IdleWatchdogPolicyOptions,
	PollingPolicy,
	PollingPolicyOptions,
	RetryPolicy,
	RetryPolicyOptions,
	TaskBoundaryPolicy,
	TaskBoundaryPolicyOptions,
	TimePolicy,
} from "./internal/scheduling/policies.js";

export function createDeadlinePolicy(options: DeadlinePolicyOptions): DeadlinePolicy {
	return createDeadlinePolicyWithClock(realClock, options);
}

export function createRetryPolicy(options: RetryPolicyOptions): RetryPolicy {
	return createRetryPolicyWithClock(realClock, options);
}

export function createPollingPolicy(options: PollingPolicyOptions): PollingPolicy {
	return createPollingPolicyWithClock(realClock, options);
}

export function createDebouncePolicy(options: DebouncePolicyOptions): DebouncePolicy {
	return createDebouncePolicyWithClock(realClock, options);
}

export function createIdleWatchdogPolicy(options: IdleWatchdogPolicyOptions): IdleWatchdogPolicy {
	return createIdleWatchdogPolicyWithClock(realClock, options);
}

export function createTaskBoundaryPolicy(options: TaskBoundaryPolicyOptions): TaskBoundaryPolicy {
	return createTaskBoundaryPolicyWithClock(realClock, options);
}

export function createExpiryPolicy(options: ExpiryPolicyOptions): ExpiryPolicy {
	return createExpiryPolicyWithClock(realClock, options);
}
